    config = function()
        require("mason").setup({})

        require("mason-lspconfig").setup({
            -- Lua, C/C++, Python, JavaScript, HTML, CSS
            ensure_installed = { "lua_ls", "clangd", "pyright", "ts_ls", "html", "cssls" },
